use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::fs::{self, File};
use std::io::{BufReader, Write};
use std::path::Path;

/// Status of an optimization proposal across its lifecycle.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ProposalStatus {
    /// Generated by SkillOpt and pending human review / approval.
    Pending,
    /// Explicitly approved by operator.
    Approved,
    /// Rejected by evaluation gate or operator.
    Rejected,
    /// Written to live `SKILL.md`.
    Applied,
    /// Reverted to previous version via rollback.
    RolledBack,
}

/// A persistent record of a proposed skill optimization.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OptimizationProposal {
    pub id: String,
    pub skill_name: String,
    pub baseline_hash: String,
    pub candidate_hash: String,
    pub baseline_score: f64,
    pub candidate_score: f64,
    pub gate_action: String,
    pub gate_reason: String,
    pub candidate_instructions: String,
    pub source_tasks: Vec<String>,
    pub created_at: u64,
    pub status: ProposalStatus,
    pub applied_at: Option<u64>,
}

/// Store for persisting optimization proposals across restarts under `.onyx/skills/proposals.json`.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct ProposalStore {
    pub proposals: HashMap<String, OptimizationProposal>,
    pub last_updated_at: u64,
}

impl ProposalStore {
    pub fn new() -> Self {
        Self::default()
    }

    /// Load or initialize proposal store from workspace root or standard Onyx home.
    pub fn load_or_init<P: AsRef<Path>>(root: P) -> Self {
        let path = root.as_ref().join(".onyx/skills/proposals.json");
        if !path.exists() {
            return Self::new();
        }

        match File::open(&path) {
            Ok(file) => {
                let reader = BufReader::new(file);
                serde_json::from_reader(reader).unwrap_or_default()
            }
            Err(_) => Self::new(),
        }
    }

    /// Record a newly mined/gated proposal.
    pub fn record_proposal(&mut self, proposal: OptimizationProposal) {
        use std::time::{SystemTime, UNIX_EPOCH};
        self.last_updated_at = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs();

        self.proposals.insert(proposal.id.clone(), proposal);
    }

    /// Mark proposal as applied, verifying it does not overwrite a newer hash.
    pub fn mark_applied(&mut self, id: &str, current_disk_hash: &str) -> Result<(), String> {
        let proposal = self
            .proposals
            .get_mut(id)
            .ok_or_else(|| format!("proposal `{id}` not found"))?;

        if proposal.baseline_hash != current_disk_hash {
            return Err(format!(
                "Stale proposal conflict! Current disk hash `{}` does not match proposal baseline `{}`",
                current_disk_hash, proposal.baseline_hash
            ));
        }

        use std::time::{SystemTime, UNIX_EPOCH};
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs();

        proposal.status = ProposalStatus::Applied;
        proposal.applied_at = Some(now);
        self.last_updated_at = now;
        Ok(())
    }

    /// Mark proposal as rolled back.
    pub fn mark_rolled_back(&mut self, id: &str) -> Result<(), String> {
        let proposal = self
            .proposals
            .get_mut(id)
            .ok_or_else(|| format!("proposal `{id}` not found"))?;

        use std::time::{SystemTime, UNIX_EPOCH};
        proposal.status = ProposalStatus::RolledBack;
        self.last_updated_at = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs();
        Ok(())
    }

    /// Save proposal store atomically to `.onyx/skills/proposals.json`.
    pub fn save_atomic<P: AsRef<Path>>(&mut self, root: P) -> std::io::Result<()> {
        let dir = root.as_ref().join(".onyx/skills");
        fs::create_dir_all(&dir)?;

        let target_file = dir.join("proposals.json");
        let temp_file = dir.join(format!(".proposals.json.tmp.{}", std::process::id()));

        let json = serde_json::to_string_pretty(self)
            .map_err(|e| std::io::Error::new(std::io::ErrorKind::Other, e))?;

        let mut file = File::create(&temp_file)?;
        file.write_all(json.as_bytes())?;
        file.sync_all()?;
        drop(file);

        fs::rename(temp_file, target_file)?;
        Ok(())
    }
}
